#!/usr/bin/env python3
"""Writes docs/PLATFORMS.md from spec/platforms.json (run it after editing the JSON)."""

from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent


def render(platforms: dict) -> str:
    lines = [
        "<!-- Generated by tools/gen_platforms_doc.py from spec/platforms.json. Do not edit by hand. -->",
        "",
        "# Canonical categories and consoles",
        "",
        "Reuse these ids in your addon so the app can merge it with other addons. See [the specification](SPEC.md#3-categories-and-consoles).",
        "",
    ]
    for category in platforms["categories"]:
        lines += [f"## {category['name']} (`{category['id']}`)", "", "| Console id | Name |", "|---|---|"]
        lines += [f"| `{console['id']}` | {console['name']} |" for console in category["consoles"]]
        lines.append("")
    return "\n".join(lines)


def main() -> None:
    platforms = json.loads((ROOT / "spec" / "platforms.json").read_text(encoding="utf-8"))
    (ROOT / "docs" / "PLATFORMS.md").write_text(render(platforms), encoding="utf-8", newline="\n")


if __name__ == "__main__":
    main()
